public final class WordingOnlyTest{public static void main(String[] args)throws Exception{String now=Files.readString(Path.of("src/com/winkreyes/excelbedrockmenu/ExcelBedrockMenu.java"));String[] labels=MenuLogicTest.parseStringArray(now,"BUTTONS"),commands=MenuLogicTest.parseStringArray(now,"COMMANDS");int index=-1;for(int i=0;i<commands.length;i++)if(commands[i].equals("wandstyle"))index=i;if(index<0||!labels[index].equals("Wand controls"))throw new AssertionError("wand wording");boolean found=false;for(int g=0;g<ExcelBedrockMenu.catalogGroupCount();g++)for(int i=0;i<ExcelBedrockMenu.catalogEntryCount(g);i++)if("mark".equals(ExcelBedrockMenu.catalogRun(g,i))){if(!ExcelBedrockMenu.catalogDescription(g,i).equals("Choose crafted/found name labels and gear-stat display"))throw new AssertionError("mark wording");found=true;}if(!found)throw new AssertionError("mark absent");System.out.println("PASS 2 explicit wording checks");}}
